args.command:
mkdir -p /tmp/probe/project/mod && cd /tmp/probe/project/mod && printf 'module example.com/myproject\n\ngo 1.21\n' > go.mod && cat > main.go <<'EOF'
package main

import (
	"example.com/myproject/pkg"
	"github.com/pkg/errors"
	"fmt"
)

func main() {
	fmt.Println(pkg.X, errors.New("x"))
}
EOF
cat go.mod; /workspace/executable -output stdout ./main.go; echo "EXIT=$?"

mkdir -p /tmp/probe/project/nogomod && cd /tmp/probe/project/nogomod && cat > f.go <<'EOF'
